# Implementation of Cache class with packer support
class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    serialized = if @packer
      @packer.dump(payload)
    else
      payload
    end
    @store[key] = { data: serialized, stale: stale }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    if @packer
      @packer.load(entry[:data])
    else
      entry[:data]
    end
  end

  def sweep
    @store.delete_if { |_key, entry| entry[:stale] }
  end
end
