class TokenStream
  attr_reader :tokens

  def initialize(tokens)
    @tokens = tokens.dup
    @index = 0
    @peek_cache = nil
    @peek_valid = false
  end

  def next
    if @index >= @tokens.size
      raise StopIteration, "No more tokens"
    end

    token = @tokens[@index]
    @index += 1
    @peek_valid = false
    @peek_cache = nil

    token
  end

  def peek
    if @index >= @tokens.size
      raise StopIteration, "No more tokens"
    end

    unless @peek_valid
      @peek_cache = @tokens[@index]
      @peek_valid = true
    end

    @peek_cache
  end

  def rewind
    @index = 0
    @peek_valid = false
    @peek_cache = nil
  end
end
