class StockCount
  attr_reader :count

  def initialize(count)
    @count = count
  end

  def -(other)
    if other.is_a?(StockCount)
      (@count - other.count).to_f
    elsif other.is_a?(Rational) || other.is_a?(Numeric)
      (@count - other).to_f
    else
      raise ArgumentError, "Cannot subtract #{other.class} from StockCount"
    end
  end

  def ==(other)
    if other.is_a?(StockCount)
      @count == other.count
    else
      false
    end
  end

  def hash
    @count.hash
  end

  def eql?(other)
    other.is_a?(StockCount) && @count == other.count
  end
end
