class KeyStore
  def initialize
    @data = {}
  end

  def store(key, value)
    @data[key] = value
    value
  end

  def fetch(key)
    if @data.key?(key)
      if block_given?
        @data[key]
      else
        @data[key]
      end
    else
      if block_given?
        yield
      else
        nil
      end
    end
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super()
    @hits = 0
    @misses = 0
  end

  def fetch(key)
    if @data.key?(key)
      @hits += 1
      if block_given?
        @data[key]
      else
        @data[key]
      end
    else
      @misses += 1
      if block_given?
        yield
      else
        nil
      end
    end
  end
end
