class Registry
  def initialize
    @objects = []
    @object_ids = {}
  end

  def register(obj)
    # Use object_id to check if this exact object is already registered
    if @object_ids.key?(obj.object_id)
      # Same object, do nothing, just return self
      return self
    end

    # Register the new object
    @objects << obj
    @object_ids[obj.object_id] = true

    self
  end

  def registered?(obj)
    # Check if this exact object (same object_id) is registered
    @object_ids.key?(obj.object_id)
  end

  def size
    @objects.size
  end

  def to_a
    @objects.dup
  end
end
```

